T = {
"gs1": ("غرفة البوصلة، الدور الثالث", "في الدور الأعلى بغرفة الـ Compass، دوس الزر الصغير عشان ترتفع المنصات. خلك يسار المنصة اللي بالنص، اقتل الـ Skulltula اللي يحرس الحافة العالية واقفز. العنكبوت على الجدار هناك."),
"gs2": ("بركة القبو، جدار النباتات", "اكسر الشبكة اللي بنص الغرفة العلوية وانزل للقبو. بعد ما تطلع من البركة لف وراك: فيه عنكبوت جنب جدار النباتات الكبير. اضربه وبعدين اطلع وخذ التوكن."),
"gs3": ("بركة القبو، الشبك الشمالي", "في نفس القبو، شوف الشبك اللي على الجهة الشمالية من الحاجز المائي. اضرب العنكبوت من بعيد وبعدين اقفز للشبك."),
"gs4": ("نباتات القبو، الغرفة الشمالية الغربية", "في الدور السفلي من القبو، روح للممرات الشمالية الغربية. في الغرفة اللي ينزل فيها ثلاث Gohma Larvae، ولّع Deku Stick من الشعلة وأحرق الشبكة اللي في الزاوية العلوية. اقتل الـ Deku Baba والـ Skulltula ورا، اضرب العنكبوت فوق على النباتات واطلع."),
"gs5": ("شجرة قرب غابة كوكيري", "اعبر الجدول الصغير في شرق السهل قرب مدخل غابة كوكيري. سوّ Roll في الشجرة الطويلة النحيفة عشان يطيح العنكبوت."),
"gs6": ("مخزن السلاح جنب البوابة", "أول ما تدخل بوابة السوق خذ أول يمين لغرفة السلاح اللي فيها الحارس الطفشان. سوّ Roll في الصناديق الكبيرة اللي بالآخر، وحدة فيها العنكبوت."),
"gs7": ("شجرة في الحديقة", "اطلع فوق غرفة الحراسة لحدائق القلعة، امشِ مع ممر الشجيرات اللي بالنص واطلع الجدار الغربي عشان تتعدى البوابة المقفلة. في المكان الصغير يمين جدار النباتات اللي على الخندق، سوّ Roll في الشجرة الطويلة النحيفة."),
"gs8": ("شجرة ورا البيت الرئيسي", "لف ورا بيت Talon للساحة الصغيرة الشمالية الشرقية اللي فيها البرج الخشبي وشجرتين. سوّ Roll في الطويلة النحيفة."),
"gs9": ("الشجرة الطويلة عند المدخل", "سوّ Roll في الشجرة الطويلة عند مدخل القرية، مكان ما المعلّم يصارخ على عماله."),
"gs10": ("باب بيت العناكب الملعون", "وقّف برا بيت العناكب بالليل. العنكبوت يطلع على الشبكة الصغيرة يسار الباب."),
"gs11": ("المبنى اللي تحت البناء", "بالليل روح للمبنى اللي تحت البناء في الجنوب قرب صاحبة الدجاج. اطلع مع السقالات لين توصل العنكبوت على حافة الطوب العالية."),
"gs12": ("سلّم برج المراقبة", "بالليل شوف سلّم البرج الخشبي الطويل اللي بنص القرية. اضرب العنكبوت وبعدين اطلع وخذ التوكن."),
"gs13": ("ورا بيت الولد", "جنوب البرج ومحل الدواء فيه بيت ولد صغير. بالليل لف وراه وتلقى العنكبوت على شبكته على الجدار."),
"gs14": ("التربة اللينة جنب الدرج", "اطلع الدرج اللي على يسار المقبرة للتربة اللينة ورا شجرة صغيرة. طلّع حشرة من القنينة عليها (تلقى حشرات تحت الحجارة عند المدخل)."),
"gs15": ("التربة اللينة ورا المحل", "إذا معك حشرة في قنينة، روح ورا محل كوكيري وطلّعها على التربة اللينة."),
"gs16": ("ورا بيت الإخوان اللي يعرفون كل شي", "بعد ما تقابل زيلدا، خلها ليل (Sun's Song أو نام في سريرك) وروح ورا بيت Know-It-All Brothers قرب ساحة التدريب. العنكبوت على جدار بيت الشجرة."),
"gs17": ("التربة اللينة على حافة الجسر", "أول ما تدخل لف يسار للمكان اللي فيه Skull Kid لحاله، وبعدين جنوب من النفق. على الحافة العالية فوق الجسر اللي يطلع من غابة كوكيري، طلّع حشرة على التربة اللينة."),
"gs18": ("التربة اللينة في مرج الـ Scrubs", "خذ الطريق اللي رايح لاختصار مدينة الغورون، يمين للماي، بعدين يسار شمال ويسار مرة ثانية لمرج فيه Deku Scrubs. طلّع حشرة على التربة اللينة جنب الشجرة الكبيرة (فيه Scrub يبيع حشرات)."),
"gs19": ("التربة اللينة في نفق كهف دودونغو", "بالـ Goron Bracelet، شيل الـ Bomb Flower اللي جنب الغوروني على الطريق وارميها على الصخرة اللي فوق كهف دودونغو. داخل النفق اللي انفتح، طلّع حشرة على التربة اللينة."),
"gs20": ("جدار متشقق في الممر الشرقي", "في أول ممر شرق صالة المدخل (الجمجمة)، بعد المكان اللي يطلع فيه ثلاث Baby Dodongos، فجّر الجدار المتشقق بقنبلة أو بـ Dodongo. العنكبوت وراه مع كم Keese."),
"gs21": ("الجدار الشبكي فوق الدرج", "روح شمال في الدور الأول للدرج المرتفع اللي حوله Bomb Flowers. حط الـ Bomb Flower اللي لحالها في الفراغ عشان تنفجر كلها وينزل الدرج. اطلع للمستوى العلوي الجنوبي، لف للجدار الشبكي، اضرب العنكبوت واطلع."),
"gs22": ("الدور الثاني، الجدار المتشقق الشمالي الشرقي", "في الدور الثاني من صالة المدخل، فجّر الجدار المتشقق في الزاوية الشمالية الشرقية جنب الجمجمة. اعبر الغرفة اللي فيها اثنين Dodongos حول صخرة؛ العنكبوت في الجهة الثانية."),
"gs23": ("Armos ورا الصخرة اللي تندف", "بعد ما تفتح ممر الجمجمة بالقنابل، ادفّ الصخرة لتحت في غرفة الممر لين آخر الجدار. فجّر الجدار المتشقق اللي على الحافة فوقها وادخل. العنكبوت مستخبي ورا Armos قرب الآخر بين Baby Dodongos."),
"gs24": ("جدار متشقق جنب الـ Tektites", "بعد اللفة من طريق كاكاريكو على طول، فجّر الجدار المتشقق قرب الـ Red Tektites. العنكبوت داخل، حتى بالنهار."),
"gs25": ("غرفة الصخور المخفية", "في الدور اللي فيه المدخل، فجّر الصخور اللي فوق على اليسار لغرفة فيها صخور وأعمدة سودا. فجّر يمين، بعدين يسار، بعدين قدام لين صندوقين فيهم Blue Rupees وصندوق خشب؛ سوّ Roll فيه وتلقى العنكبوت."),
"gs26": ("الصناديق اللي على اليسار", "اركض بسرعة لأن الحرارة تضرك بعد كم ثانية. سوّ Roll في أبعد صندوق من الاثنين اللي جنب الجرة على اليسار."),
"gs27": ("مغارة جنوب مزرعة لون لون", "في منطقة الأشجار جنوب مزرعة لون لون قرب Peahat كبير، فجّر الأرض المتشققة عشان تنفتح مغارة. العنكبوت فوق على الجدار، فارجع لها بالـ Boomerang أو الـ Hookshot."),
"gs28": ("التربة اللينة جنب بياع الفاصوليا", "فجّر الصخور اللي على النهر لين توصل بياع الـ Magic Beans. طلّع حشرة على التربة اللينة اللي جنبه على طول."),
"gs29": ("ورا الشلال", "امشِ مع النهر لين الشلال اللي مخبي مملكة زورا. انزل لتحته واطلع النباتات للمنصة اللي بالنص؛ بالليل يطلع العنكبوت ورا النباتات."),
"gs30": ("التربة اللينة جنب المختبر", "طلّع حشرة على التربة اللينة برا مختبر البحيرة."),
"gs31": ("نفق الشاطئ الجنوبي الغربي", "اسبح من جزيرة الشجرة الكبيرة للشاطئ الجنوبي الغربي. اطلع الحافة الصغيرة اللي على الطرف الجنوبي وازحف في النفق لين العنكبوت."),
"gs32": ("الأشجار جنوب الطريق", "بعد ما توري الملك زورا رسالة روتو، روح للجهة الجنوبية من النافورة، بعد الطريق الضحل لأرض فيها أشجار وجدار متشقق. سوّ Roll في الأشجار الطويلة النحيفة."),
"gs33": ("غرفة الماي اللي يرتفع، الحافة الغربية", "امشِ ورا روتو لـ B1 وروح شمال للغرفة الغارقة. دوس الزر اللي يلمع عشان يرتفع الماي، واطلع النباتات للحافة الغربية؛ العنكبوت جنب كم جرة."),
"gs34": ("غرفة الحفرة، الجدار الشمالي", "نظّف المجسات اللي سادة غرفة الحفرة اللي بدورين وانزل في الحفرة الزرقا لحافة عالية. شوف شمال بعد الـ Biri تلقى العنكبوت على الجدار، واستخدم الـ Boomerang تقتله وتجيب التوكن."),
"gs35": ("سقف الممر الشمالي الغربي", "من نفس الحافة العالية، امشِ في الممر للغرفة الشمالية الغربية. فيه عنكبوت لازق في سقف الممر؛ الـ Boomerang يطيحه ويجيب التوكن."),
"gs36": ("العمود الطويل قبل الزعيم", "في آخر غرفة كبيرة قبل الزعيم، روح ورا العمود الطويل وشوف فوق على نباتاته. اضرب العنكبوت بالـ Boomerang أو الـ Slingshot."),
"gs37": ("جدار القوس بالليل", "ارجع ومعك الـ Boomerang وشغّل Sun's Song. اطلع قوس الماي اللي قريب؛ العنكبوت يطلع على الجدار البعيد."),
"gs38": ("شباك البيت الرئيسي", "بالليل وقّف قرب البيت الرئيسي جنب مدخل المضمار. العنكبوت على شباك؛ استخدم الـ Boomerang."),
"gs39": ("حافة البرج المهدوم", "بالليل ادخل البرج المهدوم في الزاوية الجنوبية الغربية (اللي فيه قطعة القلب). اضرب العنكبوت اللي على الحافة العالية فوق النباتات بالـ Boomerang."),
"gs40": ("ورا كوخ Dampé", "بالليل روح ورا كوخ Dampé. العنكبوت على جدار عالي؛ اضربه بالـ Boomerang. وإذا كنت كبير تقدر تستخدم الـ Hookshot."),
"gs41": ("تحت الجسر الخشبي", "أول ما تدخل الوادي، عند اللوح الصغير اللي فوق البركة، شغّل Sun's Song. العنكبوت يطلع تحت الجسر؛ انزل له."),
"gs42": ("التربة اللينة عند البقرة", "خذ دجاجة قرب الجسر وطِر فيها لتحت للمكان الكبير اللي على حافة الماي. فيه Gerudo تعتني ببقرة؛ طلّع حشرة على التربة اللينة اللي قريبة."),
"gs43": ("الجسر الحبلي للمختبر", "امشِ على الجسر الحبلي اللي رايح للمختبر وشغّل Sun's Song. لف وراك تلقى العنكبوت بعيد شوي واستخدم الـ Boomerang."),
"gs44": ("إسطبل البقرة ورا بيت Impa", "بعد ما تفوز بسباق Dampé وتاخذ الـ Hookshot، ارجع بالليل. سوّ Hookshot على النباتات اللي على يسار بيت Impa القديم، ادخل إسطبل البقرة وتلقى العنكبوت هناك."),
"gs45": ("قوس غرفة الحراسة المهدومة", "اعبر الـ Redeads في السوق لين أطلال القلعة. ورا قوس غرفة الحراسة القديمة فوق الحفرة الكبيرة، العنكبوت معلّق فوق؛ سوّ له Hookshot."),
"gs46": ("سطح بيت التوأم", "نظّف الأعداء، وبالليل روح ورا بيت التوأم (الأقرب لنفق شجرة ديكو). سوّ Hookshot على العنكبوت اللي فوق."),
"gs47": ("حافة النبتة الطايرة", "وأنت صغير ازرع Magic Bean في البستان المخفي (من المدخل: يمين، يسار لاختصار الغورون، يسار لاختصار زورا، بعدين يسار مرتين). ولما تكبر اركب النبتة للحافة العالية اللي فيها العنكبوت."),
"gs48": ("الأطلال جنب نافورة الجنية", "امشِ في الممرات الضيقة واقتل الـ Moblins من ورا لين الدرج الكبير. بدل ما تطلع، لف لفتحة الأطلال اللي فيها نافورة الجنية والسلّم. في الجهة الشرقية قرب جذور الشجرة الكبيرة، سوّ Hookshot على العنكبوت اللي فوق على الجدار."),
"gs49": ("أعلى شجرة المدخل", "في غرفة المدخل اطلع شجرة النباتات الكبيرة عشان المفتاح. في أعلى شي لف وراك وسوّ Hookshot على العنكبوت."),
"gs50": ("الصالة الرئيسية، الشباك الأزرق", "في الصالة الرئيسية اللي تختفي فيها Poe Sisters، اطلع الدرج شمال للباب اللي شباكه أخضر. فوق لف يمين للشباك الأزرق وسوّ Hookshot على العنكبوت اللي على الجدار."),
}
